function bars(h){const mx=Math.max(...h.map(Math.abs),1),d=['Sen','Sel','Rab','Kam','Jum','Sab','Min'];return `<div class="bars">${h.map((v,i)=>`<div><i class="${v<0?'n':''}" style="height:${Math.max(3,Math.abs(v)/mx*62)}px"></i>${d[i]}</div>`).join('')}</div>`}
function logList(p){return p.logs.length?p.logs.map(l=>`<div class="row"><div><b>${l.t}</b> · ${l.c}<div class="mu">Masuk ${l.i} · Keluar ${l.o} ml · Nyeri ${l.p}/10</div>${l.f?`<img class="ft" src="${l.f}">`:''}</div><div style="text-align:right"><b style="color:${net(l)<0?'var(--rd)':'var(--bl)'}">${Math.abs(net(l))}</b><br><span class="tag ${l.cl=='Jernih'?'':'r'}">${l.cl}</span></div></div>`).join(''):'<div class="mu">Belum ada catatan hari ini.</div>'}
function eduList(){return E.map((e,i)=>`<div class="cd"><span class="tag">${e.k}</span><h3 style="margin-top:7px">${e.t}</h3>${e.v?`<div class="vid" onclick="toast('Demo: video ${e.v} menit')">▶ Video ${e.v} mnt</div>`:''}<div class="mu" style="color:var(--tx)">${e.b}</div>${e.q?`<div style="margin-top:9px"><b>Kuis:</b> ${e.q.q}${e.q.o.map((o,j)=>`<button class="opt ${e.an==null?'':j==e.q.a?'ok':j==e.an?'no':''}" ${U=='p'?`onclick="E[${i}].an=${j};draw();toast('${j==e.q.a?'Benar! 🎉':'Belum tepat, baca lagi ya'}')"`:''}>${o}</button>`).join('')}</div>`:''}</div>`).join('')}
function chatBox(i){const a=C[i]||[];return `<div class="cd" style="min-height:150px">${a.length?a.map(c=>`<div class="msg ${c.f==U?'me':'ot'}">${c.x}</div>`).join(''):'<div class="mu">Belum ada pesan.</div>'}</div><div style="display:flex;gap:6px"><input id="ci" placeholder="Tulis pesan..."><button class="bt s" onclick="send('${i}')">Kirim</button></div>`}
function send(i){const v=$('ci').value.trim();if(!v)return;(C[i]=C[i]||[]).push({f:U,x:v.replace(/</g,'&lt;')});draw()}
function rekap(i){const p=P[i],d=['Sen','Sel','Rab','Kam','Jum','Sab','Min'];$('pr').innerHTML=`<h2>Rekap Mingguan CAPD</h2><p>${p.n} (${p.u} th) · ${CFG.rs} · cetak ${fd('2026-11-22')}</p><table><tr><th>Hari</th><th>Balance (ml)</th></tr>${p.h.map((v,k)=>`<tr><td>${d[k]}</td><td>${v}</td></tr>`).join('')}</table><p>Rata-rata: ${Math.round(p.h.reduce((a,b)=>a+b,0)/7)} ml · BB ${p.bb} kg · TD ${p.td} · Exit site ${p.ex}<br>Transfer set terakhir ${fd(p.tsd)}, rencana ${fd(p.nxt)}<br>Riwayat peritonitis: ${p.per.map(x=>hs(x,'per')).join('; ')||'tidak ada'}</p><p class="mu">Gunakan Simpan sebagai PDF pada dialog cetak.</p>`;window.print()}
function pView(){const p=P[me],r=kp(p);
if(tab=='home')return `<div class="cd"><div class="hero"><div class="ring" style="background:conic-gradient(var(--pr) ${r*3.6}deg,var(--bd) 0)"><div>${p.logs.length}/4<small>pergantian</small></div></div><div><b style="font-size:16px">Halo, ${p.n.split(' ')[1]} 👋</b><div class="mu">Balance hari ini <b style="color:${tot(p)<0?'var(--rd)':'var(--bl)'}">${Math.abs(tot(p))} ml</b></div><div class="mu">Ganti transfer set ${dd(p.nxt)} hari lagi</div></div></div><button class="bt" onclick="go('log')">+ Catat pergantian cairan</button></div>
${remC(me)}
<div class="g"><div class="st"><b>${p.bb}</b><span class="mu">BB (kg)</span></div><div class="st"><b>${p.td}</b><span class="mu">Tensi</span></div></div>
${stokC(me)}
<div class="cd"><h3>Balance 7 hari (ml)</h3>${bars(p.h)}</div><div class="cd"><h3>Catatan hari ini</h3>${logList(p)}</div><button class="bt o" onclick="rekap(${me})">🖨️ Cetak rekap (PDF)</button>`;
if(tab=='log')return `<div class="cd"><h3>Catat pergantian cairan</h3><div class="mu">Pengganti buku catatan manual</div><div class="g" style="margin:0"><div><label>Jam</label><input id="f1" type="time" value="21:00"></div><div><label>Konsentrasi</label><select id="f2"><option>1.5%</option><option>2.5%</option><option>4.25%</option></select></div><div><label>Cairan masuk (ml)</label><input id="f3" type="number" value="2000"></div><div><label>Cairan keluar (ml)</label><input id="f4" type="number" placeholder="2300"></div><div><label>Berat badan (kg)</label><input id="f8" type="number" step=".1" value="${p.bb}"></div><div><label>Tensi</label><input id="f9" value="${p.td}"></div></div>
<label>Kondisi cairan keluar</label><select id="f5"><option>Jernih</option><option>Keruh</option><option>Berdarah/kemerahan</option><option>Ada fibrin</option></select><label>Exit site</label><select id="fa"><option>Bersih</option><option>Kemerahan</option><option>Bengkak</option><option>Keluar cairan</option></select>
<label>Nyeri perut (0–10): <b id="pv">0</b></label><input id="f6" type="range" min="0" max="10" value="0" oninput="$('pv').textContent=this.value"><label>Foto exit site / kantong (opsional)</label><input id="ff" type="file" accept="image/*" capture="environment"><label>Keluhan lain</label><textarea id="f7" rows="2"></textarea><button class="bt" onclick="saveLog()">Simpan & kirim ke perawat</button></div>`;
if(tab=='sop')return sopV('p'+me);if(tab=='edu')return `<h2>Edukasi dari perawat</h2>`+eduList();return `<h2>Konsultasi dengan perawat</h2>`+chatBox(me)}
function saveLog(){if(!$('f4').value)return toast('Isi cairan keluar dulu');const p=P[me],fl=$('ff').files[0],fin=f=>{p.logs.push({t:$('f1').value,c:$('f2').value,i:+$('f3').value,o:+$('f4').value,cl:$('f5').value,p:+$('f6').value,f});p.bb=+$('f8').value;p.td=$('f9').value;p.ex=$('fa').value;p.last='Baru saja';if(crit(p).length){(C[me]=C[me]||[]).push({f:'p',x:'⚠️ Otomatis: '+crit(p).join(', ')});toast('Peringatan dikirim ke perawat 🚨')}else toast('Tersimpan ✔');go('home')};if(fl){const r=new FileReader();r.onload=()=>fin(r.result);r.readAsDataURL(fl)}else fin(null)}
