function loginV(){return `<div class="lg"><div class="cd" style="text-align:center"><div style="font-size:46px">🏥</div><div class="mu" style="letter-spacing:1px;font-size:11px">RENAL UNIT · RSUD WELAS ASIH PROV. JAWA BARAT</div><h2 style="margin:6px 0 0;font-size:22px">Buku Catatan Harian CAPD</h2><div class="mu">WELAS CAPD · ${esc(CFG.cr)}</div><div style="text-align:left"><h3 style="margin-top:14px">Masuk ke Akun</h3><label>Username</label><input id="un" autocapitalize="none" placeholder="Ketik nama atau username..."><label>Password</label><div style="position:relative"><input id="pin" type="password" placeholder="Masukkan password..."><a onclick="const e=$('pin');e.type=e.type=='password'?'text':'password'" style="position:absolute;right:12px;top:10px;color:var(--pr);font-size:13px;font-weight:700">Lihat</a></div><label>Masuk Sebagai</label><select id="rs">${[['p','Pasien'],['c','Calon Pasien'],['n','Perawat CAPD'],['d','Dokter'],['a','Administrator']].map(x=>`<option value="${x[0]}" ${rr==x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><button class="bt" onclick="rr=$('rs').value;login()">Masuk</button></div><div class="mu" style="margin-top:12px"><a onclick="srv=!srv;draw()" style="text-decoration:underline">Ubah pengaturan server</a></div>${srv?`<div style="text-align:left"><label>URL Web App (Apps Script)</label><input id="s1" value="${ON?API:''}"><label>Token</label><input id="s2" type="password"><button class="bt o" onclick="saveSrv()">Simpan & muat ulang</button></div>`:''}<div class="mu" style="margin-top:10px;font-size:11px">${ON?'Admin awal: admin / 0000 (segera ganti password)':'DEMO · pasien: dedi/1234 · calon: wawan/5678 · perawat: perawat/1111 · dokter: dokter/9999 · admin: admin/0000'}</div></div></div>`}
