function login(){const u=$('un').value.trim().toLowerCase(),pw=$('pin').value;let ok=0;if(rr=='p'){const i=P.findIndex(p=>un(p)==u);if(i>=0&&pw==(pinU['p'+i]||'1234')){me=i;ok=1}}else if(rr=='c'){const i=Q.findIndex(q=>un(q)==u);if(i>=0&&pw==(pinU['c'+i]||'5678')){me=i;ok=1}}else{const s=S.find(x=>x.u==u&&x.r==rr);if(s&&pw==pinU['s'+u]){su=u;ok=1}}if(!ok)return toast('Username atau password salah');U=rr;tab=U=='a'?'kp':'home';sel=null;cp=-1;draw()}
function setPin(){const k=(U=='p'||U=='c')?U+me:'s'+su,cur=pinU[k]||(U=='p'?'1234':'5678');if($('p0').value!==cur)return toast('Password lama salah');const n=$('p1').value;if(!/^\d{4}$/.test(n))return toast('Password baru harus 4 angka');if(n!==$('p2').value)return toast('Ulangi password tidak sama');if(n===cur)return toast('Password baru harus berbeda');pinU[k]=n;toast('Password berhasil diganti ✔');go('home')}
