function diriV(i){const p=P[i],f=PF[i],ed=U=='n'||U=='a',F=[['jk','Jenis kelamin'],['gd','Gol. darah'],['pk','Penyebab ginjal'],['kom','Penyakit penyerta'],['alg','Alergi'],['res','Resep CAPD'],['kel','Pendamping'],['mulai','Mulai CAPD']];return `<div class="cd"><h3>👤 ${U=='p'?'Data Diri Saya':'Data Pasien'}</h3><div class="row"><span class="mu">Nama</span><b>${p.n}</b></div><div class="row"><span class="mu">Usia</span><b>${p.u} th</b></div><div class="row"><span class="mu">No. RM</span><b>${f.rm||'-'}</b></div>${F.map(x=>ed?`<label>${x[1]}</label><input id="fx_${x[0]}" ${x[0]=='mulai'?'type="date"':''} value="${f[x[0]]||''}">`:`<div class="row"><span class="mu">${x[1]}</span><b>${x[0]=='mulai'?fd(f.mulai):(f[x[0]]||'-')}</b></div>`).join('')}${ed?`<button class="bt" onclick="saveD(${i})">Simpan data</button>`:''}</div>`}
