function riwV(i){const f=PF[i],p=P[i],ed=U=='n'||U=='a',R=(h,a)=>`<div class="cd"><h3>${h}</h3>${a.length?a.map(x=>`<div class="row">${x}</div>`).join(''):'<div class="mu">Belum ada.</div>'}</div>`;return R('🏥 Riwayat rawat inap',f.ranap)+R('🩸 Riwayat transfusi',f.trf)+R('🦠 Riwayat peritonitis',p.per)+(ed?`<div class="cd"><h3>+ Tambah riwayat</h3><select id="rj"><option value="ranap">Rawat inap</option><option value="trf">Transfusi</option></select><input id="rt" placeholder="mis. Nov 2026: ..." style="margin-top:6px"><button class="bt" onclick="addR(${i})">Simpan</button></div>`:'')}
