function rcnV(i){const p=P[i],ed=U=='n'||U=='a',ch=(k,l)=>`<label>${l}</label><input type="date" value="${p[k]||''}" ${ed?`onchange="chg(${i},'${k}',this.value)"`:'disabled'}>`;return `<div class="cd"><h3>🏥 Riwayat & Rencana</h3><div class="row"><span class="mu">Transfer set terakhir</span><b>${fd(p.tsd)}</b></div>${ch('nxt','Rencana ganti transfer set')}<div class="mu" style="margin-top:6px">${dd(p.nxt)<0?'⚠️ Sudah lewat jadwal':'Sisa '+dd(p.nxt)+' hari'}</div>${ch('kon','Rencana kontrol ke RS')}</div><div class="cd"><h3>📦 Stok kantong cairan</h3><div class="row"><span>${p.stok} kantong</span><span class="tag ${sisa(p)<7?'r':''}">±${sisa(p)} hari</span></div></div>`}
function catV(i){const p=P[i],a=p.cat||[],ed=U=='n'||U=='a';return `<div class="cd"><h3>🗒️ Catatan Petugas</h3>${a.length?a.map(c=>`<div class="row"><div><div class="mu">${c.d} · ${c.w}</div>${c.x}</div></div>`).join(''):'<div class="mu">Belum ada catatan.</div>'}</div>${ed?`<div class="cd"><h3>+ Tambah catatan</h3><textarea id="cn" rows="3" placeholder="Evaluasi, instruksi, atau edukasi untuk pasien"></textarea><button class="bt" onclick="addC(${i})">Simpan catatan</button></div>`:''}`}
function addC(i){const x=$('cn').value.trim();if(!x)return toast('Isi catatan dulu');(P[i].cat=P[i].cat||[]).unshift({d:fd('2026-11-22'),w:(S.find(s=>s.u==su)||{}).n||'Petugas',x:x.replace(/</g,'&lt;')});toast('Catatan disimpan ✔');draw()}
function rekV(i){const p=P[i];return `<div class="cd"><h3>📊 Rekap 7 hari terakhir</h3><div class="mu">Arsip bulanan per tanggal menyusul; sementara menampilkan balance 7 hari.</div>${bars(p.h)}<div class="g3" style="margin:10px 0 0"><div class="st"><b>${Math.round(p.h.reduce((a,b)=>a+b,0)/7)}</b><span class="mu">Rata-rata ml</span></div><div class="st"><b>${p.h.filter(v=>v>0).length}/7</b><span class="mu">Hari balance +</span></div><div class="st"><b>${p.logs.length}</b><span class="mu">Ganti hari ini</span></div></div></div><button class="bt o" onclick="rekap(${i})">🖨️ Cetak rekap (PDF)</button>`}
function tblV(){return `<div class="cd"><h3>Daftar Pasien & Status Hari Ini</h3><div style="overflow-x:auto"><table><tr><th>RM</th><th>Nama</th><th>Terakhir isi</th><th>Status</th><th>UF hari ini</th></tr>${P.map((p,i)=>p.st=='non'?'':`<tr><td>${PF[i].rm||'-'}</td><td>${p.n}</td><td>${p.last}</td><td><span class="tag ${p.logs.length?'':'a'}">${p.logs.length?'Sudah isi':'Belum isi'}</span></td><td>${p.logs.length?Math.abs(tot(p)):'—'}</td></tr>`).join('')}</table></div></div>`}
