function kuV(){return `<div class="cd"><h3>Pengguna petugas</h3>${S.map(s=>`<div class="row"><div><b>${s.n}</b><div class="mu">${s.u} · ${RN[s.r]}</div></div><button class="bt s o" onclick="rstS('${s.u}')">Reset</button></div>`).join('')}</div><div class="cd"><h3>➕ Tambah petugas</h3><label>Nama</label><input id="u1"><label>Username</label><input id="u2" autocapitalize="none"><label>Peran</label><select id="u3"><option value="n">Perawat CAPD</option><option value="d">Dokter</option><option value="a">Administrator</option></select><label>Password awal (4 angka)</label><input id="u4" maxlength="4" inputmode="numeric"><button class="bt" onclick="addS()">Tambah</button></div>`}
