const TODAY=(()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')})();
const addD=(s,n)=>{const d=new Date(s+'T00:00:00');d.setDate(d.getDate()+n);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const fl=s=>new Date(s+'T00:00:00').toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),fs=s=>new Date(s+'T00:00:00').toLocaleDateString('id-ID',{weekday:'short',day:'numeric',month:'short'});
const esc=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');
const DY=[];let ld=TODAY,rmo=TODAY.slice(0,7);
const dget=(i,d)=>{DY[i]=DY[i]||{};return DY[i][d]=DY[i][d]||{bb0:'',bb1:'',td:'',nd:'',sh:'',ex:[],kl:'',cat:'',s:[]}};
const sv=d=>(d.s||[]).filter(x=>x&&x.sv),dt=d=>{const a=sv(d);return{n:a.length,i:a.reduce((t,x)=>t+(+x.vi||0),0),o:a.reduce((t,x)=>t+(+x.vd||0),0)}};
function recalc(i){const p=P[i],D=DY[i]||{},t=D[TODAY];p.logs=t?sv(t).map(x=>({t:x.mi||'--:--',c:x.c,i:+x.vi||0,o:+x.vd||0,cl:x.kl,p:+x.ny||0,f:null})):[];p.h=[6,5,4,3,2,1,0].map(k=>{const d=D[addD(TODAY,-k)];if(!d)return 0;const z=dt(d);return z.n?z.o-z.i:0});const L=Object.keys(D).sort().filter(k=>sv(D[k]).length||D[k].bb1).pop();if(L){const d=D[L];if(d.bb1)p.bb=+d.bb1;if(d.td)p.td=d.td;p.ex=(d.ex||[]).find(x=>x!=='Bersih')||'Bersih';p.last=(L==TODAY?'Hari ini ':fs(L)+' ')+((sv(d).slice(-1)[0]||{}).mi||'')}}
function seedD(i){const p=P[i],h=p.h.slice(),T4=['06:00','11:00','16:00','21:00'],st=(PF[i]||{}).mulai||'',PAT=[4,4,4,4,4,4,4,4,4,4,2,0,4,4,3,4,1,0,4,4,4,4,4,2,4],
mk=(d0,n,v)=>{DY[i][d0]={bb0:p.bb,bb1:p.bb,td:p.td,nd:78,sh:36.6,ex:['Bersih'],kl:'',cat:'',s:T4.slice(0,n).map(t=>({c:'1.5%',mi:t,si:'',md:t,sd:'',vi:2000,vd:2000+Math.round(v/n),kl:'Jernih',ny:0,sv:1}))}};DY[i]={};
for(let k=0;k<7;k++){const d0=addD(TODAY,-k),v=h[6-k];if(k==0){if(p.logs.length)DY[i][d0]={bb0:p.bb,bb1:p.bb,td:p.td,nd:80,sh:36.6,ex:[p.ex],kl:'',cat:'',s:p.logs.map(l=>({c:l.c,mi:l.t,si:'',md:l.t,sd:'',vi:l.i,vd:l.o,kl:l.cl,ny:l.p,sv:1}))}}else if(v)mk(d0,[4,4,3,4,4,2][(k+i)%6],v)}
if(p.last!=='3 hari lalu')for(let k=7;k<=120;k++){const d0=addD(TODAY,-k);if(st&&d0<st)break;const n=PAT[(k+i*5)%PAT.length];if(n)mk(d0,n,400+((k*37+i*53)%300))}}
if(!ON){P.forEach((_,i)=>seedD(i));P.forEach((_,i)=>recalc(i))}
