function lama(d){if(!d)return '-';const a=new Date(d+'T00:00:00'),b=new Date(TODAY+'T00:00:00');if(b<a)return 'belum mulai';let y=b.getFullYear()-a.getFullYear(),m=b.getMonth()-a.getMonth(),x=b.getDate()-a.getDate();if(x<0){m--;x+=new Date(b.getFullYear(),b.getMonth(),0).getDate()}if(m<0){y--;m+=12}return y?y+' th '+m+' bln':m?m+' bln '+x+' hr':x+' hari'}
