function setV(){const lk=CFG.lk||{},F=(id,l,v)=>`<label>${l}</label><input id="${id}" value="${esc(v)}">`;return `<h2>⚙️ Pengaturan</h2><div class="cd"><h3>🏷️ Identitas aplikasi (kop & judul)</h3>${F('c5','Kop atas (instansi / unit)',CFG.kop)}${F('c6','Judul aplikasi',CFG.judul)}${F('c7','Subjudul',CFG.sub)}${F('c8','Nama aplikasi (singkat)',CFG.app)}${F('c9','Nama RS (kop cetak / rekap)',CFG.rs)}${F('c10','Teks kredit (bawah halaman login)',CFG.cr)}<button class="bt" onclick="saveCfg()">Simpan pengaturan</button></div><div class="cd"><h3>🔒 Kunci data pasien</h3><div class="mu">Ketuk untuk mengunci / membuka. Terkunci = hanya Admin yang bisa mengubah; pasien dan perawat hanya melihat. Tersimpan otomatis.</div>${LK.map(x=>`<div class="row" onclick="tgLk('${x[0]}')"><span>${x[1]}</span><span class="tag ${lk[x[0]]?'r':''}">${lk[x[0]]?'🔒 Dikunci':'🔓 Terbuka'}</span></div>`).join('')}</div><div class="cd"><h3>Batas waktu ideal</h3><div class="g" style="margin:0"><div><label>Fill maks (menit)</label><input id="c1" type="number" value="${CFG.fm}"></div><div><label>Drain maks (menit)</label><input id="c2" type="number" value="${CFG.dm}"></div></div><label>Volume standar cairan (mL)</label><input id="c3" type="number" value="${CFG.vol}"><label>Teks peringatan berjalan</label><textarea id="c4" rows="3">${esc(CFG.ban)}</textarea><button class="bt" onclick="saveCfg()">Simpan pengaturan</button><div class="mu" style="margin-top:6px">Batas suhu hipertermi tetap &gt; 37,5°C.</div></div><div class="cd"><h3>Akses admin</h3><div class="mu">Admin dapat mengubah data pasien, riwayat, stok, catatan harian, edukasi, kontak, pengguna, dan pengaturan ini.</div></div>`}
function saveCfg(){const a=+$('c1').value,b=+$('c2').value,c=+$('c3').value;if(!(a>0&&b>0&&c>0))return toast('Isi angka yang benar');CFG.fm=a;CFG.dm=b;CFG.vol=c;CFG.ban=$('c4').value.trim()||CFG.ban;[['kop','c5'],['judul','c6'],['sub','c7'],['app','c8'],['rs','c9'],['cr','c10']].forEach(x=>{const v=$(x[1]).value.trim();if(v)CFG[x[0]]=v});document.title=CFG.app;toast('Pengaturan tersimpan ✔');draw()}
function usg(){const e=$('un'),b=$('usl');if(!e||!b)return;const q=e.value.trim().toLowerCase();if(!q){b.style.display='none';return}const L=ulist().filter(x=>x[0].indexOf(q)>=0||x[1].toLowerCase().indexOf(q)>=0).slice(0,8);b.innerHTML=L.map(x=>`<div onclick="pickU('${x[0]}')" style="padding:10px;border-bottom:1px solid var(--bd)"><b>${esc(x[0])}</b> <span class="mu">· ${esc(x[1])} · ${x[2]}</span></div>`).join('');b.style.display=L.length?'block':'none'}
function ulist(){return [...P.map(p=>[un(p),p.n,'Pasien'+(p.tl?' · lahir '+fd(p.tl):'')]),...Q.map(q=>[un(q),q.n,'Calon pasien'+(q.tl?' · lahir '+fd(q.tl):'')]),...S.map(x=>[x.u,x.n,RN[x.r]+(x.tl?' · lahir '+fd(x.tl):'')])].sort((a,b)=>a[0].localeCompare(b[0]))}

