let cfm='';
function konf(k,msg){if(cfm===k){cfm='';return true}cfm=k;toast(msg||'Ketuk sekali lagi untuk konfirmasi');setTimeout(()=>{if(cfm===k)cfm=''},4000);return false}
function stCard(i){return `<div class="cd"><h3>Status pasien</h3><div class="mu">Nonaktifkan jika pasien meninggal, pindah unit, atau berhenti CAPD. Data tetap tersimpan dan bisa diaktifkan kembali.</div><label>Alasan</label><select id="st_r"><option>Meninggal dunia</option><option>Pindah unit / RS lain</option><option>Selesai / berhenti CAPD</option><option>Lainnya</option></select><label>Catatan (opsional)</label><input id="st_c"><button class="bt" style="background:#b91c1c" onclick="nonP(${i})">Nonaktifkan pasien</button></div>`}
