function promCard(i){return `<div class="cd"><h3>Selesai pelatihan?</h3><div class="mu">Jadikan calon ini pasien CAPD aktif. Data diri dan password dipindahkan, mulai CAPD diisi hari ini.</div><button class="bt" onclick="promQ(${i})">✅ Jadikan pasien CAPD aktif</button></div>`}
function promQ(i){if(!konf('q'+i))return;const q=Q[i];P.push({n:q.n,u:q.u,tl:q.tl,un:q.un,tsd:TODAY,nxt:addD(TODAY,60),stok:0,bb:0,td:'-',ex:'Bersih',per:[],logs:[],h:[0,0,0,0,0,0,0],last:'-'});PF.push({rm:'',jk:'',gd:'',pk:'',kom:'',alg:'',mulai:TODAY,res:'',kel:'',hp:q.hp||'',ranap:[],trf:[]});const ni=P.length-1;pinU['p'+ni]=pinU['c'+i]||'5678';try{recalc(ni)}catch(e){}Q.splice(i,1);for(let j=i;j<=Q.length;j++){if(pinU['c'+(j+1)]!==undefined)pinU['c'+j]=pinU['c'+(j+1)];else delete pinU['c'+j]}sel=null;toast('Dijadikan pasien CAPD aktif ✔');draw()}
{const _n=nView;nView=function(){const h=_n();if(U!='n'&&U!='a')return h;if(typeof sel=='number'&&P[sel]&&tab!='chat')return h+stCard(sel);if(typeof sel=='string'&&sel[0]=='q'&&Q[+sel.slice(1)])return h+promCard(+sel.slice(1));if(tab=='pts'&&sel===null)return h+inactList();return h}}

