function calC(i){if(i<0||!P[i])return '';if(ld!==cl0||!cmo){cmo=ld.slice(0,7);cl0=ld}const [y,m]=cmo.split('-').map(Number),f=new Date(y,m-1,1).getDay(),dm=new Date(y,m,0).getDate(),mn=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'],nx=new Date(y,m,1),nxm=nx.getFullYear()+'-'+String(nx.getMonth()+1).padStart(2,'0'),cells=[];for(let k=0;k<f;k++)cells.push('<span></span>');for(let d=1;d<=dm;d++){const ds=cmo+'-'+String(d).padStart(2,'0'),n=dayN(i,ds);cells.push(`<button class="cd2 ${n>=4?'g':n>0?'y':''} ${ds==ld?'sl':''} ${ds==TODAY?'td':''}" ${ds>TODAY?'disabled':''} onclick="pickDay('${ds}')" title="${n} siklus">${d}${n?`<small>${n}×</small>`:''}</button>`)}return `<details class="kal" ${calOpen?'open':''} ontoggle="calOpen=this.open"><summary>📅 Kalender pengisian · ${mn[m-1]} ${y}</summary><div class="cnv"><button onclick="calM(-1)">←</button><b>${mn[m-1]} ${y}</b><button onclick="calM(1)" ${nxm>TODAY.slice(0,7)?'disabled':''}>→</button></div><div class="cgr">${['M','S','S','R','K','J','S'].map(x=>`<i>${x}</i>`).join('')}${cells.join('')}</div><div class="cle"><span class="gg">4 siklus atau lebih (lengkap)</span><span class="yy">1–3 siklus (kurang)</span><span>kosong</span></div></details>`}
