function openCal(){const i=U=='p'?me:cp;if(i<0||!P[i])return;cmo=ld.slice(0,7);const x=$('calm');if(x)x.remove();const o=document.createElement('div');o.id='calm';o.style.cssText='position:fixed;inset:0;z-index:60;background:rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;padding:16px';o.onclick=e=>{if(e.target==o)closeCal()};document.body.appendChild(o);calR(i)}
